from __future__ import annotations

from decimal import Decimal


class BusinessRuleViolation(Exception):
    code: str
    message: str

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(message)


def _numeric_value(value: object) -> Decimal:
    if value == "" or value is None:
        return Decimal(0)
    return Decimal(str(value))


def release_credit_hold(account: dict) -> tuple[dict, list[dict]]:
    if account.get("CRED_HOLD", "") != "Y":
        return dict(account), []

    if _numeric_value(account.get("CRED_LIMIT", "")) <= 0:
        raise BusinessRuleViolation(
            "E1004",
            "Cannot release credit hold with zero credit limit",
        )

    updated_account = dict(account)
    updated_account["CRED_HOLD"] = "N"

    account_id = account.get("ACCT_ID", "")
    if account_id is None:
        account_id = ""

    audits = [
        {
            "code": "CRED_HOLD_OFF",
            "entity_id": str(account_id),
        }
    ]
    return updated_account, audits
